import java.util.Scanner;
class DivideByZeroException extends Exception { DivideByZeroException(String m){super(m);} }
public class Main { static int calculate(int a,int b,String op)throws DivideByZeroException{switch(op){case "+":return Math.addExact(a,b);case "-":return Math.subtractExact(a,b);case "*":return Math.multiplyExact(a,b);case "/":if(b==0)throw new DivideByZeroException("Division by zero is not allowed");return a/b;default:throw new IllegalArgumentException("Invalid operator");}}public static void main(String[] args){Scanner sc=new Scanner(System.in);boolean done=false;while(!done){try{System.out.print("First integer: ");int a=Integer.parseInt(sc.nextLine());System.out.print("Second integer: ");int b=Integer.parseInt(sc.nextLine());System.out.print("Operator (+,-,*,/): ");String op=sc.nextLine();System.out.println("Result: "+calculate(a,b,op));done=true;}catch(NumberFormatException e){System.out.println("Enter valid integers.");}catch(DivideByZeroException|IllegalArgumentException|ArithmeticException e){System.out.println("Error: "+e.getMessage());}finally{System.out.println("Log: Attempt completed.");}}sc.close();} }
